def duration_seconds_from_text(text_value):
    normalized = ''.join(ch.lower() if (ch.isalnum() or ch == '.') else ' ' for ch in text_value)
    tokens = normalized.split()
    total = 0.0
    for index, token in enumerate(tokens):
        multiplier = None
        if token in ('second','seconds','sec','secs'):
            multiplier = 1
        elif token in ('minute','minutes','min','mins'):
            multiplier = 60
        elif token in ('hour','hours','hr','hrs'):
            multiplier = 3600
        if multiplier is not None:
            value = numeric_value(tokens[index - 1]) if index > 0 else None
            if value is not None:
                total += value * multiplier
    return int(total)
